CREATE FUNCTION public.link_os_vehicle() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN SELECT id INTO NEW.vehicle_id FROM public.vehicles WHERE public.norm_plate(plate)=public.norm_plate(NEW.plate) ORDER BY id LIMIT 1; RETURN NEW; END $$;
CREATE TRIGGER link_os_vehicle BEFORE INSERT OR UPDATE OF plate,vehicle_id ON public.ordens_servico FOR EACH ROW EXECUTE FUNCTION public.link_os_vehicle();
UPDATE public.ordens_servico o SET vehicle_id=v.id FROM public.vehicles v WHERE public.norm_plate(o.plate)=public.norm_plate(v.plate) AND o.vehicle_id IS NULL;
CREATE FUNCTION public.set_own_yard(_workshop_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(),'master') THEN RAISE EXCEPTION 'Apenas Master configura o pátio'; END IF; IF _workshop_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.workshops WHERE id=_workshop_id AND active) THEN RAISE EXCEPTION 'Escolha um local ativo'; END IF; UPDATE public.workshops SET is_own_yard=(id=_workshop_id) WHERE is_own_yard OR id=_workshop_id; IF _workshop_id IS NULL THEN UPDATE public.workshops SET is_own_yard=false WHERE is_own_yard; END IF; END $$;
REVOKE ALL ON FUNCTION public.set_own_yard(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.set_own_yard(uuid) TO authenticated;
CREATE FUNCTION public.close_workshop_stay() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.check_out_at IS DISTINCT FROM OLD.check_out_at AND NEW.check_out_at IS NOT NULL OR NEW.archived_at IS DISTINCT FROM OLD.archived_at AND NEW.archived_at IS NOT NULL OR NEW.status IS DISTINCT FROM OLD.status AND EXISTS(SELECT 1 FROM public.status_options WHERE label=NEW.status AND is_completion) THEN UPDATE public.workshop_movements SET left_at=now() WHERE appointment_id=NEW.id AND left_at IS NULL; END IF; RETURN NEW; END $$;
CREATE TRIGGER close_workshop_stay AFTER UPDATE ON public.appointments FOR EACH ROW EXECUTE FUNCTION public.close_workshop_stay();
CREATE UNIQUE INDEX one_open_workshop_stay ON public.workshop_movements(appointment_id) WHERE left_at IS NULL;
CREATE OR REPLACE FUNCTION public.record_workshop_movement(_appointment uuid,_workshop uuid,_os uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
IF auth.uid() IS NULL OR NOT(public.has_role(auth.uid(),'master') OR public.has_role(auth.uid(),'gerente') OR public.has_role(auth.uid(),'atendimento')) OR NOT EXISTS(SELECT 1 FROM public.appointments WHERE id=_appointment AND forwarded_workshop_id=_workshop AND archived_at IS NULL) OR NOT EXISTS(SELECT 1 FROM public.ordens_servico WHERE id=_os AND appointment_id=_appointment AND workshop_id=_workshop) THEN RAISE EXCEPTION 'Encaminhamento inválido'; END IF;
PERFORM 1 FROM public.appointments WHERE id=_appointment FOR UPDATE;
IF EXISTS(SELECT 1 FROM public.workshop_movements WHERE appointment_id=_appointment AND workshop_id=_workshop AND os_id=_os AND left_at IS NULL) THEN RETURN; END IF;
UPDATE public.workshop_movements SET left_at=now() WHERE appointment_id=_appointment AND left_at IS NULL;
INSERT INTO public.workshop_movements(appointment_id,workshop_id,os_id,actor_id) VALUES(_appointment,_workshop,_os,auth.uid()); END $$;
CREATE POLICY forwarding_history ON public.appointments FOR SELECT TO authenticated USING(has_access(auth.uid()) AND archived_at IS NULL AND has_module(auth.uid(),'oficina') AND (has_role(auth.uid(),'master') OR has_role(auth.uid(),'gerente') OR has_role(auth.uid(),'atendimento')));
CREATE POLICY forwarding_update ON public.appointments FOR UPDATE TO authenticated USING(has_access(auth.uid()) AND archived_at IS NULL AND has_module(auth.uid(),'oficina') AND (has_role(auth.uid(),'master') OR has_role(auth.uid(),'gerente') OR has_role(auth.uid(),'atendimento'))) WITH CHECK(has_access(auth.uid()) AND archived_at IS NULL AND (has_role(auth.uid(),'master') OR has_role(auth.uid(),'gerente') OR has_role(auth.uid(),'atendimento')));
COMMENT ON FUNCTION public.vehicle_workflow_lookup() IS 'Limited vehicle fields for OS workflow, intentionally independent from full fleet-screen access; requires OS module.';
COMMENT ON COLUMN public.status_options.show_in_yard IS 'Optional yard status filter; when none selected all non-completion statuses are shown.';
COMMENT ON COLUMN public.status_options.show_external IS 'Optional external status filter; when none selected all non-completion statuses are shown.';